CREATE VIEW core.analytic_lab_inventario_projection AS SELECT
 CONVERT(TIME(7),core.ufn_analytic_raster_time(f.[started_at],f.[started_at_nano],0) AT TIME ZONE zone.name) AS [Hora (Início)],
 CONVERT(NVARCHAR(320),CONCAT(CONVERT(NVARCHAR(36),g.run_id),N'/',i.root_type COLLATE Latin1_General_100_BIN2,N':',i.root_key,N'/',i.part_type COLLATE Latin1_General_100_BIN2,N':',i.part_key,N'/',i.component_type COLLATE Latin1_General_100_BIN2,N':',i.component_key)) AS [Identificador Único],
 f.[cnr_c_s_fit_corporation_sequence_number] AS [Nº Minuta],
 f.[cnr_c_s_fit_pyr_nickname] AS [Pagador],
 f.[cnr_c_s_fit_sdr_nickname] AS [Remetente],
 f.[cnr_c_s_fit_sdr_ads_cty_name] AS [Origem],
 f.[cnr_c_s_fit_rpt_nickname] AS [Destinatário],
 f.[cnr_c_s_fit_rpt_ads_cty_name] AS [Destino],
 f.[cnr_c_s_fit_dyn_name] AS [Região Entrega],
 f.[cnr_c_s_fit_dyn_drt_nickname] AS [Filial Entregadora],
 f.[sequence_code] AS [N° Ordem],
 branch.normalized_name AS [Filial],
 branch.normalized_name AS [Filial da Ordem de Conferência],
 COALESCE(freight_branch.normalized_name,branch.normalized_name) AS [Filial Emissora do Frete],
 COALESCE((SELECT l.label COLLATE Latin1_General_100_BIN2 FROM ref.analytic_lab_label l WHERE l.reference_release_id=selection.reference_release_id AND l.category='INV_TYPE' AND l.raw_value=kind.type_token COLLATE Latin1_General_100_BIN2),kind.type_token) AS [Tipo],
 core.ufn_analytic_raster_time(f.[started_at],f.[started_at_nano],0) AT TIME ZONE zone.name AS [Data/Hora início],
 core.ufn_analytic_raster_time(f.[finished_at],f.[finished_at_nano],0) AT TIME ZONE zone.name AS [Data/Hora fim],
 COALESCE((SELECT l.label COLLATE Latin1_General_100_BIN2 FROM ref.analytic_lab_label l WHERE l.reference_release_id=selection.reference_release_id AND l.category='INV_STATUS' AND l.raw_value=f.status COLLATE Latin1_General_100_BIN2),f.status) AS [Status],
 f.[cnr_cis_eoe_psn_name] AS [Conferente],
 notes.display_names AS [Notas Fiscais],
 f.[cnr_c_s_fit_invoices_value] AS [Valor de NF],
 f.[cnr_c_s_fit_real_weight] AS [Peso Real],
 f.[cnr_c_s_fit_total_cubic_volume] AS [M³],
 f.[cnr_c_s_fit_taxed_weight] AS [Peso Taxado],
 f.[cnr_c_s_fit_invoices_volumes] AS [Volumes],
 f.[cnr_c_s_read_volumes] AS [Volumes Lidos],
 core.ufn_analytic_raster_time(f.[cnr_c_s_fit_dpn_delivery_prediction_at],f.[cnr_c_s_fit_dpn_delivery_prediction_at_nano],0) AT TIME ZONE zone.name AS [Previsão de Entrega],
 core.ufn_analytic_raster_time(f.[cnr_c_s_fit_dpn_performance_finished_at],f.[cnr_c_s_fit_dpn_performance_finished_at_nano],0) AT TIME ZONE zone.name AS [Finalização da Performance],
 core.ufn_analytic_raster_time(f.[cnr_c_s_fit_dpn_performance_finished_at],f.[cnr_c_s_fit_dpn_performance_finished_at_nano],0) AT TIME ZONE zone.name AS [Data de Finalização],
 core.ufn_analytic_raster_time(f.[cnr_c_s_fit_fte_lce_occurrence_at],f.[cnr_c_s_fit_fte_lce_occurrence_at_nano],0) AT TIME ZONE zone.name AS [Data Última Ocorrência],
 f.[cnr_c_s_fit_fte_lce_ore_description] AS [Ocorrência],
 CONVERT(NVARCHAR(3),CASE i.proof_attached WHEN 1 THEN N'Sim' ELSE N'Não' END) AS [Comprovante Anexado],
 (SELECT i.execution_id,i.occurrence,i.observation_id,i.revision,f.[cnr_c_s_fit_corporation_sequence_number_p] AS [cnr_c_s_fit_corporation_sequence_number.presence],f.[cnr_c_s_fit_corporation_sequence_number_w] AS [cnr_c_s_fit_corporation_sequence_number.wire],f.[cnr_c_s_fit_corporation_sequence_number_raw] AS [cnr_c_s_fit_corporation_sequence_number.raw],f.[cnr_c_s_fit_dpn_delivery_prediction_at_p] AS [cnr_c_s_fit_dpn_delivery_prediction_at.presence],f.[cnr_c_s_fit_dpn_delivery_prediction_at_w] AS [cnr_c_s_fit_dpn_delivery_prediction_at.wire],f.[cnr_c_s_fit_dpn_delivery_prediction_at_raw] AS [cnr_c_s_fit_dpn_delivery_prediction_at.raw],f.[cnr_c_s_fit_dpn_performance_finished_at_p] AS [cnr_c_s_fit_dpn_performance_finished_at.presence],f.[cnr_c_s_fit_dpn_performance_finished_at_w] AS [cnr_c_s_fit_dpn_performance_finished_at.wire],f.[cnr_c_s_fit_dpn_performance_finished_at_raw] AS [cnr_c_s_fit_dpn_performance_finished_at.raw],f.[cnr_c_s_fit_dyn_drt_nickname_p] AS [cnr_c_s_fit_dyn_drt_nickname.presence],f.[cnr_c_s_fit_dyn_drt_nickname_w] AS [cnr_c_s_fit_dyn_drt_nickname.wire],f.[cnr_c_s_fit_dyn_drt_nickname_raw] AS [cnr_c_s_fit_dyn_drt_nickname.raw],f.[cnr_c_s_fit_dyn_name_p] AS [cnr_c_s_fit_dyn_name.presence],f.[cnr_c_s_fit_dyn_name_w] AS [cnr_c_s_fit_dyn_name.wire],f.[cnr_c_s_fit_dyn_name_raw] AS [cnr_c_s_fit_dyn_name.raw],f.[cnr_c_s_fit_fte_lce_occurrence_at_p] AS [cnr_c_s_fit_fte_lce_occurrence_at.presence],f.[cnr_c_s_fit_fte_lce_occurrence_at_w] AS [cnr_c_s_fit_fte_lce_occurrence_at.wire],f.[cnr_c_s_fit_fte_lce_occurrence_at_raw] AS [cnr_c_s_fit_fte_lce_occurrence_at.raw],f.[cnr_c_s_fit_fte_lce_ore_description_p] AS [cnr_c_s_fit_fte_lce_ore_description.presence],f.[cnr_c_s_fit_fte_lce_ore_description_w] AS [cnr_c_s_fit_fte_lce_ore_description.wire],f.[cnr_c_s_fit_fte_lce_ore_description_raw] AS [cnr_c_s_fit_fte_lce_ore_description.raw],f.[cnr_c_s_fit_invoices_mapping_p] AS [cnr_c_s_fit_invoices_mapping.presence],f.[cnr_c_s_fit_invoices_mapping_w] AS [cnr_c_s_fit_invoices_mapping.wire],f.[cnr_c_s_fit_invoices_mapping_raw] AS [cnr_c_s_fit_invoices_mapping.raw],f.[cnr_c_s_fit_invoices_value_p] AS [cnr_c_s_fit_invoices_value.presence],f.[cnr_c_s_fit_invoices_value_w] AS [cnr_c_s_fit_invoices_value.wire],f.[cnr_c_s_fit_invoices_value_raw] AS [cnr_c_s_fit_invoices_value.raw],f.[cnr_c_s_fit_invoices_volumes_p] AS [cnr_c_s_fit_invoices_volumes.presence],f.[cnr_c_s_fit_invoices_volumes_w] AS [cnr_c_s_fit_invoices_volumes.wire],f.[cnr_c_s_fit_invoices_volumes_raw] AS [cnr_c_s_fit_invoices_volumes.raw],f.[cnr_c_s_fit_pyr_nickname_p] AS [cnr_c_s_fit_pyr_nickname.presence],f.[cnr_c_s_fit_pyr_nickname_w] AS [cnr_c_s_fit_pyr_nickname.wire],f.[cnr_c_s_fit_pyr_nickname_raw] AS [cnr_c_s_fit_pyr_nickname.raw],f.[cnr_c_s_fit_real_weight_p] AS [cnr_c_s_fit_real_weight.presence],f.[cnr_c_s_fit_real_weight_w] AS [cnr_c_s_fit_real_weight.wire],f.[cnr_c_s_fit_real_weight_raw] AS [cnr_c_s_fit_real_weight.raw],f.[cnr_c_s_fit_rpt_ads_cty_name_p] AS [cnr_c_s_fit_rpt_ads_cty_name.presence],f.[cnr_c_s_fit_rpt_ads_cty_name_w] AS [cnr_c_s_fit_rpt_ads_cty_name.wire],f.[cnr_c_s_fit_rpt_ads_cty_name_raw] AS [cnr_c_s_fit_rpt_ads_cty_name.raw],f.[cnr_c_s_fit_rpt_nickname_p] AS [cnr_c_s_fit_rpt_nickname.presence],f.[cnr_c_s_fit_rpt_nickname_w] AS [cnr_c_s_fit_rpt_nickname.wire],f.[cnr_c_s_fit_rpt_nickname_raw] AS [cnr_c_s_fit_rpt_nickname.raw],f.[cnr_c_s_fit_sdr_ads_cty_name_p] AS [cnr_c_s_fit_sdr_ads_cty_name.presence],f.[cnr_c_s_fit_sdr_ads_cty_name_w] AS [cnr_c_s_fit_sdr_ads_cty_name.wire],f.[cnr_c_s_fit_sdr_ads_cty_name_raw] AS [cnr_c_s_fit_sdr_ads_cty_name.raw],f.[cnr_c_s_fit_sdr_nickname_p] AS [cnr_c_s_fit_sdr_nickname.presence],f.[cnr_c_s_fit_sdr_nickname_w] AS [cnr_c_s_fit_sdr_nickname.wire],f.[cnr_c_s_fit_sdr_nickname_raw] AS [cnr_c_s_fit_sdr_nickname.raw],f.[cnr_c_s_fit_taxed_weight_p] AS [cnr_c_s_fit_taxed_weight.presence],f.[cnr_c_s_fit_taxed_weight_w] AS [cnr_c_s_fit_taxed_weight.wire],f.[cnr_c_s_fit_taxed_weight_raw] AS [cnr_c_s_fit_taxed_weight.raw],f.[cnr_c_s_fit_total_cubic_volume_p] AS [cnr_c_s_fit_total_cubic_volume.presence],f.[cnr_c_s_fit_total_cubic_volume_w] AS [cnr_c_s_fit_total_cubic_volume.wire],f.[cnr_c_s_fit_total_cubic_volume_raw] AS [cnr_c_s_fit_total_cubic_volume.raw],f.[cnr_c_s_read_volumes_p] AS [cnr_c_s_read_volumes.presence],f.[cnr_c_s_read_volumes_w] AS [cnr_c_s_read_volumes.wire],f.[cnr_c_s_read_volumes_raw] AS [cnr_c_s_read_volumes.raw],f.[cnr_cis_eoe_psn_name_p] AS [cnr_cis_eoe_psn_name.presence],f.[cnr_cis_eoe_psn_name_w] AS [cnr_cis_eoe_psn_name.wire],f.[cnr_cis_eoe_psn_name_raw] AS [cnr_cis_eoe_psn_name.raw],f.[cnr_crn_psn_nickname_p] AS [cnr_crn_psn_nickname.presence],f.[cnr_crn_psn_nickname_w] AS [cnr_crn_psn_nickname.wire],f.[cnr_crn_psn_nickname_raw] AS [cnr_crn_psn_nickname.raw],f.[finished_at_p] AS [finished_at.presence],f.[finished_at_w] AS [finished_at.wire],f.[finished_at_raw] AS [finished_at.raw],f.[sequence_code_p] AS [sequence_code.presence],f.[sequence_code_w] AS [sequence_code.wire],f.[sequence_code_raw] AS [sequence_code.raw],f.[started_at_p] AS [started_at.presence],f.[started_at_w] AS [started_at.wire],f.[started_at_raw] AS [started_at.raw],f.[status_p] AS [status.presence],f.[status_w] AS [status.wire],f.[status_raw] AS [status.raw],f.[type_p] AS [type.presence],f.[type_w] AS [type.wire],f.[type_raw] AS [type.raw] FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER) AS [Metadata],
 capture.sealed_at AS [Data de extracao],
 g.run_id,CONVERT(NVARCHAR(256),CONCAT(i.root_type COLLATE Latin1_General_100_BIN2,N':',i.root_key)) source_key,i.component_id,i.root_id,i.observation_id,i.execution_id,i.occurrence,
 dates.business_date,selection.revision reference_revision,selection.reference_release_id,branch.binding_id branch_binding_id,
 freight.dependency_id freight_dependency_id,freight_branch.binding_id freight_branch_binding_id,
 CONVERT(VARCHAR(40),CASE WHEN freight_branch.disposition='RESOLVED' THEN 'EXPLICIT_INV_FREIGHT_BRANCH' ELSE 'INVENTORY_BRANCH_FALLBACK' END) issuer_branch_provenance,
 f.cnr_crn_psn_nickname branch_raw,f.type type_raw,f.status status_raw,
 CONVERT(VARCHAR(40),CASE WHEN i.unresolved_conflict=1 THEN 'SOURCE_CONFLICT' WHEN dates.business_date IS NULL THEN 'BUSINESS_DATE_MISSING'
 WHEN selection.reference_release_id IS NULL THEN 'REFERENCE_MISSING' WHEN ISNULL(branch.disposition,'MISSING')<>'RESOLVED' THEN 'BRANCH_UNRESOLVED'
 WHEN freight.target_count>1 THEN 'FREIGHT_RELATION_AMBIGUOUS' WHEN freight.blocked>0 THEN 'FREIGHT_RELATION_UNRESOLVED' WHEN freight.target_count=1 AND ISNULL(freight_branch.disposition,'MISSING')<>'RESOLVED' THEN 'FREIGHT_BRANCH_UNRESOLVED'
 ELSE 'READY' END) disposition
 FROM ctl.analytic_lab_source_group g JOIN ctl.analytic_lab_run run ON run.run_id=g.run_id
 JOIN core.expansion_lab_current_input i ON i.run_id=g.expansion_run AND i.vertical='INV'
 JOIN stg.expansion_lab_inv f ON f.execution_id=i.execution_id AND f.occurrence=i.occurrence
 JOIN ctl.expansion_lab_capture capture ON capture.execution_id=i.execution_id
 CROSS APPLY(SELECT CASE run.zone_id WHEN 'UTC' THEN 'UTC' ELSE 'E. South America Standard Time' END name) zone
 CROSS APPLY(SELECT CONVERT(DATE,core.ufn_analytic_raster_time(f.started_at,f.started_at_nano,0) AT TIME ZONE zone.name) business_date) dates
 LEFT JOIN ctl.analytic_lab_reference_selection selection ON selection.run_id=g.run_id AND selection.valid_from<=dates.business_date AND selection.valid_to_exclusive>dates.business_date
 OUTER APPLY(SELECT * FROM ref.ufn_analytic_dimension(g.run_id,selection.revision,dates.business_date) d WHERE d.entity='INV' AND d.source_key=CONCAT(i.root_type COLLATE Latin1_General_100_BIN2,N':',i.root_key) COLLATE Latin1_General_100_BIN2 AND d.role='BRANCH') branch
 CROSS APPLY(SELECT CASE WHEN f.type LIKE N'CheckIn::Order::%' THEN SUBSTRING(f.type,17,1024) ELSE f.type END type_token) kind
 OUTER APPLY(SELECT STRING_AGG(CONVERT(NVARCHAR(4000),a.text_value),N', ') WITHIN GROUP(ORDER BY a.physical_position) display_names
 FROM stg.expansion_lab_array_item a WHERE a.execution_id=i.execution_id AND a.occurrence=i.occurrence AND a.field_name='cnr_c_s_fit_invoices_mapping') notes
 OUTER APPLY(SELECT COUNT(DISTINCT link.target_dependency_id) target_count,CASE WHEN COUNT(DISTINCT link.target_dependency_id)=1 THEN MIN(link.target_dependency_id) END dependency_id,
 SUM(CASE WHEN link.state NOT IN('RESOLVED','SUPERSEDED','INACTIVE') THEN 1 ELSE 0 END) blocked
 FROM core.expansion_lab_link link JOIN stg.expansion_lab_relation declared ON declared.relation_id=link.relation_id
 WHERE link.run_id=g.expansion_run AND link.component_id=i.component_id AND declared.kind='INV_FREIGHT' AND link.state NOT IN('SUPERSEDED','INACTIVE')) freight
 LEFT JOIN core.expansion_lab_dependency dependency ON dependency.dependency_id=freight.dependency_id
 OUTER APPLY(SELECT * FROM ref.ufn_analytic_dimension(g.run_id,selection.revision,dates.business_date) d WHERE d.entity='FRETE' AND d.source_key=dependency.source_key AND d.role='BRANCH') freight_branch;
 
GO
CREATE VIEW pub.analytic_lab_sql_11 AS SELECT * FROM core.analytic_lab_inventario_projection WHERE disposition='READY';
GO
CREATE VIEW core.analytic_lab_sinistros_projection AS SELECT
 CONVERT(NVARCHAR(320),CONCAT(CONVERT(NVARCHAR(36),g.run_id),N'/',i.root_type COLLATE Latin1_General_100_BIN2,N':',i.root_key,N'/',i.part_type COLLATE Latin1_General_100_BIN2,N':',i.part_key,N'/',i.component_type COLLATE Latin1_General_100_BIN2,N':',i.component_key)) AS [Identificador Único],
 f.[sequence_code] AS [Nº do Sinistro],
 f.[opening_at_date] AS [Data abertura],
 f.[occurrence_at_date] AS [Data ocorrência],
 CONVERT(TIME(7),core.ufn_analytic_raster_time(f.[occurrence_at_time]/1000000000,CONVERT(INT,f.[occurrence_at_time]%1000000000),0)) AS [Hora ocorrência],
 f.[expected_solution_date] AS [Previsão de solução],
 f.[insurance_claim_location] AS [Local do sinistro],
 f.[informed_by] AS [Informado por],
 f.[finished_at_date] AS [Data finalização],
 CONVERT(TIME(7),core.ufn_analytic_raster_time(f.[finished_at_time]/1000000000,CONVERT(INT,f.[finished_at_time]%1000000000),0)) AS [Hora finalização],
 f.[invoices_count] AS [Quantidade de documentos],
 f.[icm_fis_fit_corporation_sequence_number] AS [Minuta],
 f.[icm_fis_ioe_number] AS [Nota Fiscal/Número],
 f.[invoices_volumes] AS [Volumes],
 f.[invoices_weight] AS [Peso],
 f.[invoices_value] AS [Valor NF],
 f.[icm_fis_fit_pyr_nickname] AS [Pagador do frete/Nome fantasia],
 f.[customer_debits_subtotal] AS [valor a pagar ao cliente],
 f.[customer_credit_entries_subtotal] AS [Valor nota de crédito ao cliente],
 f.[responsible_credits_subtotal] AS [Valor a receber do responsável],
 f.[responsible_debit_entries_subtotal] AS [Valor nota de débito do responsável],
 f.[insurer_credits_subtotal] AS [Valor a receber da seguradora],
 f.[insurance_claim_total] AS [Resultado final],
 branch.normalized_name AS [Pessoa/Nome fantasia],
 f.[icm_dvr_iil_name] AS [Ocorrência/Ocorrência],
 f.[icm_fer_name] AS [Usuário/Nome],
 vehicle.license_plate AS [Veículo/Placa],
 f.[icm_ttt_ore_description] AS [Ocorrência/Descrição],
 f.[icm_ttt_ore_code] AS [Ocorrência/Código],
 core.ufn_analytic_raster_time(f.[icm_ttt_treatment_at],f.[icm_ttt_treatment_at_nano],0) AT TIME ZONE zone.name AS [Tratativa/Data tratativa],
 COALESCE((SELECT l.label COLLATE Latin1_General_100_BIN2 FROM ref.analytic_lab_label l WHERE l.reference_release_id=selection.reference_release_id AND l.category='SIN_DEALING' AND l.raw_value=f.icm_ttt_dealing_type COLLATE Latin1_General_100_BIN2),f.icm_ttt_dealing_type) AS [Tratativa/Tipo tratativa],
 COALESCE((SELECT l.label COLLATE Latin1_General_100_BIN2 FROM ref.analytic_lab_label l WHERE l.reference_release_id=selection.reference_release_id AND l.category='SIN_SOLUTION' AND l.raw_value=f.icm_ttt_solution_type COLLATE Latin1_General_100_BIN2),f.icm_ttt_solution_type) AS [Tratativa/Solução],
 (SELECT i.execution_id,i.occurrence,i.observation_id,i.revision,f.[bo_number_p] AS [bo_number.presence],f.[bo_number_w] AS [bo_number.wire],f.[bo_number_raw] AS [bo_number.raw],f.[brokers_case_number_p] AS [brokers_case_number.presence],f.[brokers_case_number_w] AS [brokers_case_number.wire],f.[brokers_case_number_raw] AS [brokers_case_number.raw],f.[customer_communication_contact_name_p] AS [customer_communication_contact_name.presence],f.[customer_communication_contact_name_w] AS [customer_communication_contact_name.wire],f.[customer_communication_contact_name_raw] AS [customer_communication_contact_name.raw],f.[customer_communication_date_p] AS [customer_communication_date.presence],f.[customer_communication_date_w] AS [customer_communication_date.wire],f.[customer_communication_date_raw] AS [customer_communication_date.raw],f.[customer_communication_time_p] AS [customer_communication_time.presence],f.[customer_communication_time_w] AS [customer_communication_time.wire],f.[customer_communication_time_raw] AS [customer_communication_time.raw],f.[customer_credit_entries_subtotal_p] AS [customer_credit_entries_subtotal.presence],f.[customer_credit_entries_subtotal_w] AS [customer_credit_entries_subtotal.wire],f.[customer_credit_entries_subtotal_raw] AS [customer_credit_entries_subtotal.raw],f.[customer_debits_subtotal_p] AS [customer_debits_subtotal.presence],f.[customer_debits_subtotal_w] AS [customer_debits_subtotal.wire],f.[customer_debits_subtotal_raw] AS [customer_debits_subtotal.raw],f.[expected_solution_date_p] AS [expected_solution_date.presence],f.[expected_solution_date_w] AS [expected_solution_date.wire],f.[expected_solution_date_raw] AS [expected_solution_date.raw],f.[finished_at_date_p] AS [finished_at_date.presence],f.[finished_at_date_w] AS [finished_at_date.wire],f.[finished_at_date_raw] AS [finished_at_date.raw],f.[finished_at_time_p] AS [finished_at_time.presence],f.[finished_at_time_w] AS [finished_at_time.wire],f.[finished_at_time_raw] AS [finished_at_time.raw],f.[finished_commentary_p] AS [finished_commentary.presence],f.[finished_commentary_w] AS [finished_commentary.wire],f.[finished_commentary_raw] AS [finished_commentary.raw],f.[icm_crn_psn_nickname_p] AS [icm_crn_psn_nickname.presence],f.[icm_crn_psn_nickname_w] AS [icm_crn_psn_nickname.wire],f.[icm_crn_psn_nickname_raw] AS [icm_crn_psn_nickname.raw],f.[icm_dvr_iil_name_p] AS [icm_dvr_iil_name.presence],f.[icm_dvr_iil_name_w] AS [icm_dvr_iil_name.wire],f.[icm_dvr_iil_name_raw] AS [icm_dvr_iil_name.raw],f.[icm_fer_name_p] AS [icm_fer_name.presence],f.[icm_fer_name_w] AS [icm_fer_name.wire],f.[icm_fer_name_raw] AS [icm_fer_name.raw],f.[icm_fis_fit_corporation_sequence_number_p] AS [icm_fis_fit_corporation_sequence_number.presence],f.[icm_fis_fit_corporation_sequence_number_w] AS [icm_fis_fit_corporation_sequence_number.wire],f.[icm_fis_fit_corporation_sequence_number_raw] AS [icm_fis_fit_corporation_sequence_number.raw],f.[icm_fis_fit_pyr_nickname_p] AS [icm_fis_fit_pyr_nickname.presence],f.[icm_fis_fit_pyr_nickname_w] AS [icm_fis_fit_pyr_nickname.wire],f.[icm_fis_fit_pyr_nickname_raw] AS [icm_fis_fit_pyr_nickname.raw],f.[icm_fis_ioe_number_p] AS [icm_fis_ioe_number.presence],f.[icm_fis_ioe_number_w] AS [icm_fis_ioe_number.wire],f.[icm_fis_ioe_number_raw] AS [icm_fis_ioe_number.raw],f.[icm_ttt_dealing_type_p] AS [icm_ttt_dealing_type.presence],f.[icm_ttt_dealing_type_w] AS [icm_ttt_dealing_type.wire],f.[icm_ttt_dealing_type_raw] AS [icm_ttt_dealing_type.raw],f.[icm_ttt_ore_code_p] AS [icm_ttt_ore_code.presence],f.[icm_ttt_ore_code_w] AS [icm_ttt_ore_code.wire],f.[icm_ttt_ore_code_raw] AS [icm_ttt_ore_code.raw],f.[icm_ttt_ore_description_p] AS [icm_ttt_ore_description.presence],f.[icm_ttt_ore_description_w] AS [icm_ttt_ore_description.wire],f.[icm_ttt_ore_description_raw] AS [icm_ttt_ore_description.raw],f.[icm_ttt_solution_type_p] AS [icm_ttt_solution_type.presence],f.[icm_ttt_solution_type_w] AS [icm_ttt_solution_type.wire],f.[icm_ttt_solution_type_raw] AS [icm_ttt_solution_type.raw],f.[icm_ttt_treatment_at_p] AS [icm_ttt_treatment_at.presence],f.[icm_ttt_treatment_at_w] AS [icm_ttt_treatment_at.wire],f.[icm_ttt_treatment_at_raw] AS [icm_ttt_treatment_at.raw],f.[icm_vie_license_plate_p] AS [icm_vie_license_plate.presence],f.[icm_vie_license_plate_w] AS [icm_vie_license_plate.wire],f.[icm_vie_license_plate_raw] AS [icm_vie_license_plate.raw],f.[informed_by_p] AS [informed_by.presence],f.[informed_by_w] AS [informed_by.wire],f.[informed_by_raw] AS [informed_by.raw],f.[insurance_claim_commentary_p] AS [insurance_claim_commentary.presence],f.[insurance_claim_commentary_w] AS [insurance_claim_commentary.wire],f.[insurance_claim_commentary_raw] AS [insurance_claim_commentary.raw],f.[insurance_claim_location_p] AS [insurance_claim_location.presence],f.[insurance_claim_location_w] AS [insurance_claim_location.wire],f.[insurance_claim_location_raw] AS [insurance_claim_location.raw],f.[insurance_claim_total_p] AS [insurance_claim_total.presence],f.[insurance_claim_total_w] AS [insurance_claim_total.wire],f.[insurance_claim_total_raw] AS [insurance_claim_total.raw],f.[insurer_credits_subtotal_p] AS [insurer_credits_subtotal.presence],f.[insurer_credits_subtotal_w] AS [insurer_credits_subtotal.wire],f.[insurer_credits_subtotal_raw] AS [insurer_credits_subtotal.raw],f.[internal_description_p] AS [internal_description.presence],f.[internal_description_w] AS [internal_description.wire],f.[internal_description_raw] AS [internal_description.raw],f.[invoices_count_p] AS [invoices_count.presence],f.[invoices_count_w] AS [invoices_count.wire],f.[invoices_count_raw] AS [invoices_count.raw],f.[invoices_value_p] AS [invoices_value.presence],f.[invoices_value_w] AS [invoices_value.wire],f.[invoices_value_raw] AS [invoices_value.raw],f.[invoices_volumes_p] AS [invoices_volumes.presence],f.[invoices_volumes_w] AS [invoices_volumes.wire],f.[invoices_volumes_raw] AS [invoices_volumes.raw],f.[invoices_weight_p] AS [invoices_weight.presence],f.[invoices_weight_w] AS [invoices_weight.wire],f.[invoices_weight_raw] AS [invoices_weight.raw],f.[list_of_claimed_products_p] AS [list_of_claimed_products.presence],f.[list_of_claimed_products_w] AS [list_of_claimed_products.wire],f.[list_of_claimed_products_raw] AS [list_of_claimed_products.raw],f.[occurrence_at_date_p] AS [occurrence_at_date.presence],f.[occurrence_at_date_w] AS [occurrence_at_date.wire],f.[occurrence_at_date_raw] AS [occurrence_at_date.raw],f.[occurrence_at_time_p] AS [occurrence_at_time.presence],f.[occurrence_at_time_w] AS [occurrence_at_time.wire],f.[occurrence_at_time_raw] AS [occurrence_at_time.raw],f.[opening_at_date_p] AS [opening_at_date.presence],f.[opening_at_date_w] AS [opening_at_date.wire],f.[opening_at_date_raw] AS [opening_at_date.raw],f.[policy_number_p] AS [policy_number.presence],f.[policy_number_w] AS [policy_number.wire],f.[policy_number_raw] AS [policy_number.raw],f.[rcfdc_p] AS [rcfdc.presence],f.[rcfdc_w] AS [rcfdc.wire],f.[rcfdc_raw] AS [rcfdc.raw],f.[rctac_p] AS [rctac.presence],f.[rctac_w] AS [rctac.wire],f.[rctac_raw] AS [rctac.raw],f.[rctrc_p] AS [rctrc.presence],f.[rctrc_w] AS [rctrc.wire],f.[rctrc_raw] AS [rctrc.raw],f.[responsible_credits_subtotal_p] AS [responsible_credits_subtotal.presence],f.[responsible_credits_subtotal_w] AS [responsible_credits_subtotal.wire],f.[responsible_credits_subtotal_raw] AS [responsible_credits_subtotal.raw],f.[responsible_debit_entries_subtotal_p] AS [responsible_debit_entries_subtotal.presence],f.[responsible_debit_entries_subtotal_w] AS [responsible_debit_entries_subtotal.wire],f.[responsible_debit_entries_subtotal_raw] AS [responsible_debit_entries_subtotal.raw],f.[sequence_code_p] AS [sequence_code.presence],f.[sequence_code_w] AS [sequence_code.wire],f.[sequence_code_raw] AS [sequence_code.raw] FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER) AS [Metadata],
 capture.sealed_at AS [Data de extracao],
 g.run_id,CONVERT(NVARCHAR(256),CONCAT(i.root_type COLLATE Latin1_General_100_BIN2,N':',i.root_key)) source_key,i.component_id,i.root_id,i.observation_id,i.execution_id,i.occurrence,
 dates.business_date,selection.revision reference_revision,selection.reference_release_id,branch.binding_id branch_binding_id,
 vehicle.binding_id vehicle_binding_id,f.icm_vie_license_plate vehicle_plate_raw,f.icm_crn_psn_nickname branch_raw,f.icm_ttt_dealing_type dealing_type_raw,f.icm_ttt_solution_type solution_type_raw,
 CONVERT(VARCHAR(40),CASE WHEN i.unresolved_conflict=1 THEN 'SOURCE_CONFLICT' WHEN dates.business_date IS NULL THEN 'BUSINESS_DATE_MISSING'
 WHEN selection.reference_release_id IS NULL THEN 'REFERENCE_MISSING' WHEN ISNULL(branch.disposition,'MISSING')<>'RESOLVED' THEN 'BRANCH_UNRESOLVED'
 WHEN ISNULL(vehicle.disposition,'MISSING')<>'RESOLVED' THEN 'VEHICLE_UNRESOLVED'
 ELSE 'READY' END) disposition
 FROM ctl.analytic_lab_source_group g JOIN ctl.analytic_lab_run run ON run.run_id=g.run_id
 JOIN core.expansion_lab_current_input i ON i.run_id=g.expansion_run AND i.vertical='SIN'
 JOIN stg.expansion_lab_sin f ON f.execution_id=i.execution_id AND f.occurrence=i.occurrence
 JOIN ctl.expansion_lab_capture capture ON capture.execution_id=i.execution_id
 CROSS APPLY(SELECT CASE run.zone_id WHEN 'UTC' THEN 'UTC' ELSE 'E. South America Standard Time' END name) zone
 CROSS APPLY(SELECT f.opening_at_date business_date) dates
 LEFT JOIN ctl.analytic_lab_reference_selection selection ON selection.run_id=g.run_id AND selection.valid_from<=dates.business_date AND selection.valid_to_exclusive>dates.business_date
 OUTER APPLY(SELECT * FROM ref.ufn_analytic_dimension(g.run_id,selection.revision,dates.business_date) d WHERE d.entity='SIN' AND d.source_key=CONCAT(i.root_type COLLATE Latin1_General_100_BIN2,N':',i.root_key) COLLATE Latin1_General_100_BIN2 AND d.role='BRANCH') branch
 OUTER APPLY(SELECT * FROM ref.ufn_analytic_dimension(g.run_id,selection.revision,dates.business_date) d WHERE d.entity='SIN' AND d.source_key=CONCAT(i.root_type COLLATE Latin1_General_100_BIN2,N':',i.root_key) COLLATE Latin1_General_100_BIN2 AND d.role='TRACTOR') vehicle;
 
GO
CREATE VIEW pub.analytic_lab_sql_12 AS SELECT * FROM core.analytic_lab_sinistros_projection WHERE disposition='READY';
